825 :         // check decomposed matrix data range
826 :         double sumOffDiag = 0;
827 :         for (int i = 0; i < n - 1; ++i) {
828 :             final int fourI = 4 * i;
829 :             final double ei = work[fourI + 2];
830 :             sumOffDiag += ei;
831 :         }
832 : 
833 :         if (sumOffDiag == 0) {
834 :             // matrix is already diagonal
835 :             return;
836 :         }
837 : 
838 :         // initial checks for splits (see Parlett & Marques section 3.3)
839 :         flipIfWarranted(n, 2);
840 : 
841 :         // two iterations with Li's test for initial splits
842 :         initialSplits(n);
843 : 
844 :         // initialize parameters used by goodStep
845 :         tType = 0;
846 :         dMin1 = 0;
847 :         dMin2 = 0;
848 :         dN    = 0;
849 :         dN1   = 0;
850 :         dN2   = 0;
851 :         tau   = 0;
852 : 
853 :         // process split segments
854 :         int i0 = 0;
855 :         int n0 = n;
856 :         while (n0 > 0) {
857 : 
858 :             // retrieve shift that was temporarily stored as a negative off-diagonal element
859 :             sigma    = (n0 == n) ? 0 : -work[4 * n0 - 2];
860 :             sigmaLow = 0;
861 : 
862 :             // find start of a new split segment to process
863 :             double offDiagMin = (i0 == n0) ? 0 : work[4 * n0 - 6];
864 :             double offDiagMax = 0;
865 :             double diagMax    = work[4 * n0 - 4];
866 :             double diagMin    = diagMax;
867 :             i0 = 0;
868 :             for (int i = 4 * (n0 - 2); i >= 0; i -= 4) {
869 :                 if (work[i + 2] <= 0) {
870 :                     i0 = 1 + i / 4;
871 :                     break;
872 :                 }
873 :                 if (diagMin >= 4 * offDiagMax) {
874 :                     diagMin    = Math.min(diagMin, work[i + 4]);
875 :                     offDiagMax = Math.max(offDiagMax, work[i + 2]);
876 :                 }
877 :                 diagMax    = Math.max(diagMax, work[i] + work[i + 2]);
878 :                 offDiagMin = Math.min(offDiagMin, work[i + 2]);
879 :             }
880 :             work[4 * n0 - 2] = offDiagMin;
881 : 
882 :             // lower bound of Gershgorin disk
883 :             dMin = -Math.max(0, diagMin - 2 * Math.sqrt(diagMin * offDiagMax));
884 : 
885 :             pingPong = 0;
886 :             int maxIter = 30 * (n0 - i0);
887 :             for (int k = 0; i0 < n0; ++k) {
888 :                 if (k >= maxIter) {
889 :                     throw new InvalidMatrixException(new MaxIterationsExceededException(maxIter));
890 :                 }
891 : 
892 :                 // perform one step
893 :                 n0 = goodStep(i0, n0);
894 :                 pingPong = 1 - pingPong;
895 : 
896 :                 // check for new splits after "ping" steps
897 :                 // when the last elements of qd array are very small
898 :                 if ((pingPong == 0) && (n0 - i0 > 3) &&
899 :                     (work[4 * n0 - 1] <= TOLERANCE_2 * diagMax) &&
900 :                     (work[4 * n0 - 2] <= TOLERANCE_2 * sigma)) {
901 :                     int split  = i0 - 1;
902 :                     diagMax    = work[4 * i0];
903 :                     offDiagMin = work[4 * i0 + 2];
904 :                     double previousEMin = work[4 * i0 + 3];
905 :                     for (int i = 4 * i0; i < 4 * n0 - 11; i += 4) {
906 :                         if ((work[i + 3] <= TOLERANCE_2 * work[i]) &&
907 :                             (work[i + 2] <= TOLERANCE_2 * sigma)) {
908 :                             // insert a split
909 :                             work[i + 2]  = -sigma;
910 :                             split        = i / 4;
911 :                             diagMax      = 0;
912 :                             offDiagMin   = work[i + 6];
913 :                             previousEMin = work[i + 7];
914 :                         } else {
915 :                             diagMax      = Math.max(diagMax, work[i + 4]);
916 :                             offDiagMin   = Math.min(offDiagMin, work[i + 2]);
917 :                             previousEMin = Math.min(previousEMin, work[i + 3]);
918 :                         }
919 :                     }
920 :                     work[4 * n0 - 2] = offDiagMin;
921 :                     work[4 * n0 - 1] = previousEMin;
922 :                     i0 = split + 1;
923 :                 }
