"1154 :     private double[] eigenvaluesRange(final int index, final int n) {
1155 : 
1156 :         // find the bounds of the spectra of the local block
1157 :         final int lowerStart = 4 * main.length;
1158 :         final int upperStart = 5 * main.length;
1159 :         double lower = Double.POSITIVE_INFINITY;
1160 :         double upper = Double.NEGATIVE_INFINITY;
1161 :         for (int i = 0; i < n; ++i) {
1162 :             lower = Math.min(lower, work[lowerStart + index +i]);
1163 :             upper = Math.max(upper, work[upperStart + index +i]);
1164 :         }
1165 : 
1166 :         // set thresholds
1167 :         final double tNorm = Math.max(Math.abs(lower), Math.abs(upper));
1168 :         final double relativeTolerance = Math.sqrt(MathUtils.EPSILON);
1169 :         final double absoluteTolerance = 4 * minPivot;
1170 :         final int maxIter =
1171 :             2 + (int) ((Math.log(tNorm + minPivot) - Math.log(minPivot)) / Math.log(2.0));
1172 :         final double margin = 2 * (tNorm * MathUtils.EPSILON * n + 2 * minPivot);
1173 : 
1174 :         // search lower eigenvalue
1175 :         double left  = lower - margin;
1176 :         double right = upper + margin;
1177 :         for (int i = 0; i < maxIter; ++i) {
1178 : 
1179 :             final double range = right - left;
1180 :             if ((range < absoluteTolerance) ||
1181 :                 (range < relativeTolerance * Math.max(Math.abs(left), Math.abs(right)))) {
1182 :                 // search has converged
1183 :                 break;
1184 :             }
1185 : 
1186 :             final double middle = 0.5 * (left + right);
1187 :             if (countEigenValues(middle, index, n) >= 1) {
1188 :                 right = middle;
1189 :             } else {
1190 :                 left = middle;
1191 :             }
1192 : 
1193 :         }
1194 :         lower = Math.max(lower, left - 100 * MathUtils.EPSILON * Math.abs(left));
1195 : 
1196 :         // search upper eigenvalue
1197 :         left  = lower - margin;
1198 :         right = upper + margin;
1199 :         for (int i = 0; i < maxIter; ++i) {
1200 : 
1201 :             final double range = right - left;
1202 :             if ((range < absoluteTolerance) ||
1203 :                 (range < relativeTolerance * Math.max(Math.abs(left), Math.abs(right)))) {
1204 :                 // search has converged
1205 :                 break;
1206 :             }
1207 : 
1208 :             final double middle = 0.5 * (left + right);
1209 :             if (countEigenValues(middle, index, n) >= n) {
1210 :                 right = middle;
1211 :             } else {
1212 :                 left = middle;
1213 :             }
1214 : 
1215 :         }
1216 :         upper = Math.min(upper, right + 100 * MathUtils.EPSILON * Math.abs(right));
1217 : 
1218 :         return new double[] { lower, upper };
1219 : 
