1232 :         for (int i = 1; i < n; ++i) {
1233 :             ratio = main[index + i] - squaredSecondary[index + i - 1] / ratio - t;
1234 :             if (ratio <= 0) {
1235 :                 ++count;
1236 :             }
1237 :         }
